JSON.stringify((function(){
    const g=s=>{const e=document.querySelector(s);if(!e)return null;const r=e.getBoundingClientRect();return {t:Math.round(r.top),b:Math.round(r.bottom),l:Math.round(r.left),r:Math.round(r.right)};};
    const panel=g('[data-im="batch-list"]'), bar=g('[data-im="board-toolbar"]'), submit=g('[data-im="submit"]'), entry=g('[data-im="batch-entry"]');
    const ov=(a,b)=>!!a&&!!b&&a.l<b.r&&b.l<a.r&&a.t<b.b&&b.t<a.b;
    const el=document.querySelector('[data-im="batch-list"]');
    const se=document.querySelector('[data-im="submit"]');
    const hit=se?(function(){const r=se.getBoundingClientRect();const x=document.elementFromPoint(Math.round(r.left+r.width/2),Math.round(r.top+r.height/2));return !!(x&&(x===se||se.contains(x)));})():null;
    return {panel, bar, submit, entry, panelOverToolbar:ov(panel,bar), submitHit:hit, panelScrollable: el?el.scrollHeight>el.clientHeight:null, maxH: el?el.style.maxHeight:null, overflowX: document.documentElement.scrollWidth>window.innerWidth};
  })())

